// vmu.c — Dreamcast VMU emulation, reconstructed from pico2maple flipped-bt ("Mar 4 2026").
// Draft generated by local coder from the session's reverse-engineering spec, then reviewed
// and corrected against the decompilation (see recon/notes/vmu.md for evidence).
//
// The engine: Maple-facing state, block and LCD transfers, bank selection. Where the image is
// kept and what shows the LCD sit behind vmu_t's store and display sinks (vmu.h); their
// instance, internal flash + SD + the OLED, is vmu_backend.c.
#include <string.h>
#include <stdio.h>
#include "pico/stdlib.h"
#include "vmu.h"

// ---- display fan-out: every sink gets each op it implements ----
#define SINKS(u, op, ...)                                                      \
    do {                                                                       \
        for (int i_ = 0; i_ < VMU_MAX_SINKS; i_++) {                           \
            const vmu_display_t *d_ = (u)->sinks[i_];                          \
            if (d_ && d_->op) d_->op(d_->ctx, ##__VA_ARGS__);                  \
        }                                                                      \
    } while (0)

static const char devinfo_name[30 + 1]    = "Visual Memory                 ";
static const char devinfo_license[60 + 1] =
    "Produced By or Under License From SEGA ENTERPRISES,LTD.     ";

// Shared body filler for the 112-byte device-info payload. from 0x10000824 / 0x10002568
static void fill_devinfo_body(uint8_t *body)
{
    memset(body, 0, 112);
    body[3]  = 0x0e;                     // functions: storage|LCD|clock (BE u32 0x0E000000)
    body[4]  = 0x7e; body[5] = 0x7e;     // storage fdata 0x403f7e7e
    body[6]  = 0x3f; body[7] = 0x40;
    body[9]  = 0x05; body[10] = 0x10;    // LCD fdata 0x00100500
    body[13] = 0x0f; body[14] = 0x41;    // clock fdata 0x00410f00
    body[16] = 0xff;                     // area code
    body[17] = 0x00;                     // connector direction
    memcpy(body + 0x12, devinfo_name, 30);
    memcpy(body + 0x30, devinfo_license, 60);
    uint32_t power = 0x0082007c;         // standby 12.4mA, max 13.0mA
    memcpy(body + 0x6c, &power, 4);
}

// from 0x10000824
void vmu_build_device_info(vmu_devinfo_ref_t *ref, uint8_t *body)
{
    fill_devinfo_body(body);
    ref->header = 0;                     // header word filled by caller // TODO(verify @0x10000824 DAT_100008ec)
    ref->body = body;
}

// from 0x10002250
void vmu_media_info_build(vmu_state_t *v)
{
    uint8_t *m = v->media_resp;
    memset(m, 0, 0x1c);
    m[3] = 0x02;                          // func 0x02000000 (storage, BE)
    m[4] = 0xff;                          // partition / 0xff block marker
    // real-VMU geometry words (DAT_100022c8/cc): total 255, FAT 254 size 1, dir 253 size 13
    m[8] = 0xff; m[9] = 0x00; m[10] = 0xfe; m[11] = 0x00;
    m[12] = 0x01; m[13] = 0x00; m[14] = 0xfd; m[15] = 0x00;
    m[0x10] = 0x0d;                       // directory size
    uint16_t icon = v->image[0x1FE4E];    // icon shape from root block
    memcpy(m + 0x12, &icon, 2);
    m[0x14] = 200;                        // user capacity in blocks
    m[0x16] = 0x1f;
    m[0x1a] = 0x80;
    // NOTE: exact byte positions of 0xd/200/icon within media_resp follow the original
    // stores at +0x20429/+0x2042b/+0x2042d/+0x2042f/+0x20433 (media_resp +0x10/+0x12/+0x14/
    // +0x16/+0x1a). // verified against FUN_10002250
}

// from 0x10002354 — returns 0, -1 (bad bank), 0xfe (file error), 0xff (bad mode)
int vmu_load_bank_image(vmu_t *u, unsigned bank)
{
    vmu_state_t *v = &u->st;
    if (bank > 10) return -1;
    v->bank = (uint8_t)bank;
    SINKS(u, bank, bank);

    int r = u->store->load(u->store->ctx, v);
    if (r) return r;

    bool valid = true;
    for (int i = 0; i < 16; i++)
        if (v->image[0x1FE00 + i] != 0x55) { valid = false; break; }
    if (!valid) {
        r = u->store->format(u->store->ctx, v);   // (the original's vmu_format_bank + re-read)
        if (r) return r;
    }

    vmu_media_info_build(v);
    v->dirty_mask = 0;
    return 0;
}

// from 0x10002568
int vmu_init(vmu_t *u)
{
    vmu_state_t *v = &u->st;
    v->storage_mode = u->store->mode(u->store->ctx);
    SINKS(u, storage, v->storage_mode == 0);
    int r = vmu_load_bank_image(u, 1);
    if (r == 0xfe) {                  // SD failed → fall back to internal banks
        v->storage_mode = 0;
        SINKS(u, storage, true);
        if (vmu_load_bank_image(u, 1)) return -1;
    }

    fill_devinfo_body(v->devinfo_body);
    memcpy(v->mediainfo_tmpl, "Pico2Maple USBBT", 16);
    memset(v->staging, 0, sizeof v->staging);
    v->lcd_info[0] = 0; v->lcd_info[1] = 0; v->lcd_info[2] = 0; v->lcd_info[3] = 4;
    uint32_t lcd = 0x02101f2f;        // 47x31 px, 0x10 bytes/row, 2 ??  (48x32 1bpp)
    memcpy(v->lcd_info + 4, &lcd, 4);

    if (u->store->opened) u->store->opened(u->store->ctx, v);   // their store: SD export

    memset(v->gameid, 0, sizeof v->gameid);
    memset(v->gameid_aux, 0, sizeof v->gameid_aux);
    return 0;
}

// from 0x10002748
int vmu_block_read(vmu_state_t *v, uint32_t spec)
{
    if (spec & 0xff0000) return -1;              // phased reads unsupported
    memcpy(v->blk_resp_data, &v->image[(spec & 0xff) * 0x200], 0x200);
    v->blk_resp_blockno = __builtin_bswap32(spec);
    v->blk_resp_func = 0x02000000;
    return 0;
}

// from 0x1000278c — flush ONE dirty 4KB page per call; returns 1 if flushed, 0 if clean
int vmu_flush_dirty(vmu_t *u)
{
    vmu_state_t *v = &u->st;
    uint32_t mask = v->dirty_mask;
    if (mask == 0) return 0;
    unsigned page = (unsigned)__builtin_ctz(mask);

    if (!u->store->flush_page(u->store->ctx, v, page)) return 0;
    v->dirty_mask &= ~(1u << page);

    if (v->dirty_mask == 0) {
        SINKS(u, sd_icon, true);
        SINKS(u, refresh);
    }
    return 1;
}

// from 0x100028a4 — Maple BLOCK_WRITE: 4 phases of 128 bytes per 512B block
int vmu_block_write(vmu_t *u, uint32_t spec, const uint32_t *src, int words)
{
    vmu_state_t *v = &u->st;
    if (words > 0) {
        uint32_t off = (((spec >> 16) & 0xff) + (spec & 0xff) * 4) * 0x80;
        uint32_t *dst = (uint32_t *)(v->image + off);
        for (int i = 0; i < words; i++)
            dst[i] = __builtin_bswap32(src[i]);
    }
    v->dirty_mask |= 1u << ((spec & 0xff) >> 3);
    SINKS(u, sd_icon, false);
    SINKS(u, refresh);
    return 0;
}

// from 0x1000290c
int vmu_lcd_write(vmu_state_t *v, uint32_t spec, const uint32_t *src, int words)
{
    (void)spec;
    uint32_t bytes = (uint32_t)words * 4;
    uint32_t *dst = (uint32_t *)v->lcd_fb;
    for (int i = 0; i < words && (unsigned)i * 4 < 0xC0; i++)
        dst[i] = __builtin_bswap32(src[i]);
    if (bytes < 0xC0)
        memset(v->lcd_fb + bytes, 0, 0xC0 - bytes);
    return 0;
}

// from 0x100028f4 — the original upscaled into the OLED and kicked a refresh; that is now the
// OLED sink's lcd op, and any other sink gets the same frame.
int vmu_lcd_render_notify(vmu_t *u)
{
    SINKS(u, lcd, u->st.lcd_fb);
    return 0;
}

// from 0x10002948
int vmu_load_bank(vmu_t *u, unsigned bank, bool notify)
{
    vmu_state_t *v = &u->st;
    while (vmu_flush_dirty(u))
        ;
    vmu_load_bank_image(u, bank);
    fill_devinfo_body(v->devinfo_body);          // original re-stores the same bytes
    vmu_media_info_build(v);
    memset(v->staging, 0, sizeof v->staging);
    SINKS(u, bank, bank);
    if (notify) SINKS(u, refresh);
    return 0;
}

// from 0x10002aa0
int vmu_load_gameid_bank(vmu_t *u, bool notify)
{
    if (u->st.storage_mode == 1 && u->st.gameid[0] != 0)
        return vmu_load_bank(u, 10, notify);
    return -1;
}

// from 0x10002ac4
void vmu_bank_cycle(vmu_t *u, bool forward)
{
    vmu_state_t *v = &u->st;
    if (v->storage_mode == 1 && v->gameid[0] != 0) {
        if ((!forward && v->bank == 0) || (forward && v->bank == 9)) {
            vmu_load_bank(u, 10, true);
            return;
        }
    }
    unsigned nb;
    if (!forward) nb = (v->bank == 0) ? 9 : v->bank - 1u;
    else          nb = (v->bank < 9) ? v->bank + 1u : 0;
    vmu_load_bank(u, nb, true);
}

// from 0x10002b44 — store GameID (command 0x21 payload); Dreamcast BIOS id is blacklisted
int vmu_gameid_store(vmu_state_t *v, const uint32_t *w, unsigned len_words)
{
    if (len_words < 4) return -1;
    if (w[1] == 0x44434249 && w[2] == 0x4f530000)   // raw wire words of the BIOS/menu id
        return -1;
    uint32_t id[3] = { __builtin_bswap32(w[1]), __builtin_bswap32(w[2]),
                       __builtin_bswap32(w[3]) };
    memcpy(v->gameid, id, 12);
    if (len_words == 4) {
        memset(v->gameid_aux, 0, sizeof v->gameid_aux);
    } else {
        for (unsigned i = 4; i < len_words && (i - 4) * 4 < sizeof v->gameid_aux; i++) {
            uint32_t x = __builtin_bswap32(w[i]);
            memcpy(v->gameid_aux + (i - 4) * 4, &x, 4);
        }
    }
    return 0;
}

// from 0x10002bbc — SET_CONDITION on the clock function: VMU buzzer
extern void buzzer_set(uint8_t a, uint8_t b, int mode);                  // 0x1000811c
int vmu_set_condition(vmu_state_t *v, const uint32_t *frame)
{
    (void)v;
    if (frame[0] != 8) return 0;                   // only the clock function beeps
    const uint8_t *b = (const uint8_t *)frame;
    buzzer_set(b[7], b[6], 8);
    return 0;
}

// ---- Slot 1 on the sub-device table ----------------------------------------------
// The VMU arms of the original core1 dispatch (0x10000298), moved: same headers, bodies and
// order. Each runs on core1 inside the reply budget.
#include "maple_frames.h"
extern int settings_read_field(int field, void *v, int x);   // 0x10004218

static uint32_t rd32(const uint8_t *p) { uint32_t w; memcpy(&w, p, 4); return w; }

int vmu_subdev_handle(void *ctx, const maple_req_t *rq, maple_frame_t *out)
{
    vmu_t *u = ctx;
    vmu_state_t *v = &u->st;
    const uint8_t *f = rq->frame;
    const int ack = MAPLE_SUBDEV_REPLY;
    out->header = MAPLE_HDR_ACK_SUB;
    out->payload = 0;

    switch (rq->cmd) {
    case MAPLE_CMD_DEVICE_REQUEST:
        out->header = MAPLE_HDR_DEVICE_STATUS_VMU;          // DAT_100008ec: 0x0500011c
        out->payload = v->devinfo_body;
        return MAPLE_SUBDEV_REPLY;

    case MAPLE_CMD_ALL_STATUS_REQ:
        return 0;                                          // sub-devices don't answer (raw gate)

    case MAPLE_CMD_GET_CONDITION: {
        // Games poll the VMU functions (clock/storage) with GET_CONDITION; unanswered polls
        // make the console drop the whole device. Echo the function with an all-zero
        // condition (MapleSyrup does the same).
        static uint8_t vmu_cond[8];
        memset(vmu_cond, 0, sizeof vmu_cond);
        vmu_cond[3] = (uint8_t)rq->func;
        out->header = MAPLE_HDR_DATA_SHORT_VMU;            // 0x08000102 (2 words)
        out->payload = vmu_cond;
        return MAPLE_SUBDEV_REPLY;
    }

    case MAPLE_CMD_GET_MEDIA_INFO:
        if (rq->func == MAPLE_FUNC_STORAGE) {
            vmu_media_info_build(v);
            out->header = MAPLE_HDR_DATA_MEDIA_INFO;       // 0x08000107 (7 words)
            out->payload = v->media_resp;
            return MAPLE_SUBDEV_REPLY;
        }
        if (rq->func == MAPLE_FUNC_LCD) {
            // func 0x04 + LCD geometry word (48x32 1bpp)  TODO(verify @auStack_33 content)
            static const uint8_t lcd_minfo[8] = { 0,0,0,0x04, 0x00,0x10,0x1f,0x2f };
            out->header = MAPLE_HDR_DATA_SHORT_VMU;        // 0x08000102 (2 words)
            out->payload = lcd_minfo;
            return MAPLE_SUBDEV_REPLY;
        }
        return 0;

    case MAPLE_CMD_BLOCK_READ:
        if (rq->func != MAPLE_FUNC_STORAGE) return 0;
        if (vmu_block_read(v, rd32(f + 8)) == 0) {
            out->header = MAPLE_HDR_DATA_BLOCK_READ;       // 0x08000182 (130 words)
            out->payload = (const uint8_t *)&v->blk_resp_func;   // blk_resp_func..data
        } else {
            out->header = MAPLE_HDR_ERR_SUB;               // 0xfc000200 (DAT_100021cc)
        }
        return MAPLE_SUBDEV_REPLY | MAPLE_SUBDEV_IDLE_RESET;

    case MAPLE_CMD_BLOCK_WRITE:
        if (rq->func == MAPLE_FUNC_STORAGE) {
            vmu_block_write(u, rd32(f + 8), (const uint32_t *)(f + 12), rq->len - 2);
            return ack;
        }
        if (rq->func == MAPLE_FUNC_LCD) {
            vmu_lcd_write(v, rd32(f + 8), (const uint32_t *)(f + 12), rq->len - 2);
            vmu_lcd_render_notify(u);
            return ack;
        }
        return 0;

    case MAPLE_CMD_GET_LAST_ERROR:                         // write sync
        if (rq->func != MAPLE_FUNC_STORAGE) return 0;
        return ack | MAPLE_SUBDEV_IDLE_RESET;

    case MAPLE_CMD_SET_CONDITION:                          // clock function: buzzer
        // The function word is the first payload word, f+4. The original handed f+8, so
        // vmu_set_condition compared the condition word against the clock code and the
        // buzzer never sounded.
        if (vmu_set_condition(v, (const uint32_t *)(f + 4))) return 0;
        return ack;

    case MAPLE_CMD_GAMEID:                                 // OpenMenu/GDEMU GameID (custom)
        // ack_then_gid: acknowledge, then switch to the per-game bank if gameid mode is on.
        // The original sent an empty frame where the ack belonged on the success path.
        if (vmu_gameid_store(v, (const uint32_t *)(f + 4), rq->len) != 0) return ack;
        return ack | MAPLE_SUBDEV_AFTER;

    default:
        return 0;
    }
}

void vmu_subdev_after(void *ctx)
{
    char en = 0;
    if (settings_read_field(8, &en, true) && en) vmu_load_gameid_bank(ctx, true);
}

void vmu_subdev_tick(void *ctx, uint32_t idle_frames)
{
    if (idle_frames > 100) vmu_flush_dirty(ctx);
}
